public class Cadastro { private final String cpf; private String nome,email; public Cadastro(String cpf,String nome,String email){this.cpf=cpf;setNome(nome);setEmail(email);} public String getCpf(){return cpf;} public String getNome(){return nome;} public void setNome(String n){if(n!=null&&!n.isBlank())nome=n.trim();} public String getEmail(){return email;} public void setEmail(String e){if(e!=null&&e.contains("@"))email=e.trim().toLowerCase();} public static void main(String[] a){System.out.println(new Cadastro("123","Ana","ANA@UNICAP.BR").getEmail());}}
